public final class MainActivity extends Activity {
    int detailSeason=-1;
    final PremiumLibrary premium=new PremiumLibrary(this);
    static final int BLACK=Color.rgb(12,12,14),PANEL=Color.rgb(27,27,30),GOLD=Color.rgb(228,192,132),WHITE=Color.rgb(244,241,235),MUTED=Color.rgb(160,157,151);
    DataStore data;LinearLayout root,body,nav;ScrollView scroller;TextView status;String page="Home",detail="",search="",attachId="";boolean active=false,syncing=false;Handler handler=new Handler(Looper.getMainLooper());long renderRevision=0;
    final Runnable syncTick=new Runnable(){public void run(){if(active){sync(false);handler.postDelayed(this,15000);}}};
    @Override public void onCreate(Bundle saved){super.onCreate(saved);data=NoirApp.data;if(saved!=null){page=saved.getString("page","Home");detail=saved.getString("detail","");}render();handleLink(getIntent());}
    @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);handleLink(i);}
    void handleLink(Intent i){if(i.getData()!=null&&"noir".equals(i.getData().getScheme()))pair(i.getData().toString());}
    @Override protected void onResume(){super.onResume();active=true;render();handler.removeCallbacks(syncTick);handler.post(syncTick);}
    @Override protected void onPause(){active=false;handler.removeCallbacks(syncTick);super.onPause();}
    @Override protected void onSaveInstanceState(Bundle b){b.putString("page",page);b.putString("detail",detail);super.onSaveInstanceState(b);}
    @Override public void onBackPressed(){if(!detail.isEmpty()){detail="";render();}else if(!page.equals("Home")){page="Home";render();}else super.onBackPressed();}
    void sync(boolean report){if(syncing||!data.paired())return;syncing=true;String before=data.items().toString();data.network.execute(()->{String error="";try{data.sync();}catch(Exception e){error=e.getMessage();}String message=error;boolean changed=!before.equals(data.items().toString());runOnUiThread(()->{syncing=false;if(active){if(changed&&search.isEmpty()&&!page.equals("Settings")){int y=scroller==null?0:scroller.getScrollY();render();scroller.post(()->scroller.scrollTo(0,y));}else if(status!=null)status.setText(data.connection);if(report&&!message.isEmpty())toast(message);}});});}
    void pair(String link){new AlertDialog.Builder(this).setTitle("Connect to your PC?").setMessage("Noir will sync your watch history and stream videos from the PC shown in this pairing link. Keep both devices on the same home Wi-Fi.").setNegativeButton("Cancel",null).setPositiveButton("Connect",(d,w)->{status.setText("Connecting…");data.network.execute(()->{try{data.pair(link);runOnUiThread(()->{page="Home";detail="";render();toast("Paired. Your library is ready.");});}catch(Exception e){runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Couldn't connect").setMessage(e.getMessage()+"\n\nKeep Noir open on your PC and use its Settings → Pair a phone.").setPositiveButton("OK",null).show());}});}).show();}
    int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
    static GradientDrawable bg(int color,float radius){GradientDrawable b=new GradientDrawable();b.setColor(color);b.setCornerRadius(radius);return b;}
    LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setLineSpacing(dp(3),1);return t;}
    TextView heading(String s){TextView t=text(s,23,WHITE);t.setTypeface(null,Typeface.BOLD);t.setPadding(0,dp(24),0,dp(12));body.addView(t);return t;}
    void paragraph(String s){TextView t=text(s,14,MUTED);t.setPadding(0,dp(6),0,dp(12));body.addView(t);}
    Button button(String s,Runnable action,boolean primary){Button b=new Button(this);b.setAllCaps(false);b.setText(s);b.setTextColor(primary?BLACK:WHITE);b.setTextSize(14);b.setBackground(bg(primary?GOLD:PANEL,dp(12)));b.setPadding(dp(16),dp(10),dp(16),dp(10));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.setMargins(0,dp(6),0,dp(6));b.setLayoutParams(p);b.setOnClickListener(v->action.run());return b;}
    void render(){renderRevision++;root=column();root.setBackgroundColor(BLACK);root.setFitsSystemWindows(true);setContentView(root);
        LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(22),dp(12),dp(22),dp(10));TextView logo=text("NOIR",22,GOLD);logo.setLetterSpacing(.14f);logo.setTypeface(null,Typeface.BOLD);header.addView(logo,new LinearLayout.LayoutParams(0,-2,1));status=text(data.connection,11,MUTED);status.setGravity(Gravity.RIGHT);header.addView(status);root.addView(header);
        ScrollView scroll=new ScrollView(this);scroller=scroll;scroll.setFillViewport(true);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body=column();body.setPadding(dp(22),0,dp(22),dp(28));scroll.addView(body);
        nav=new LinearLayout(this);nav.setBackgroundColor(PANEL);for(String label:new String[]{"Home","Library","History","Discover","More"}){TextView t=text(label,12,(page.equals(label)||label.equals("More")&&page.equals("Settings"))?GOLD:MUTED);t.setGravity(Gravity.CENTER);t.setPadding(0,dp(17),0,dp(17));t.setOnClickListener(v->{if(label.equals("Discover")){startActivity(new Intent(this,DiscoverActivity.class));return;}if(label.equals("More")){new AlertDialog.Builder(this).setTitle("Noir").setItems(new String[]{"Downloads","Sync now","Settings"},(d,n)->{if(n==0)startActivity(new Intent(this,DownloadHubActivity.class));else if(n==1)sync(true);else{page="Settings";detail="";render();}}).show();return;}page=label;detail="";search="";render();});nav.addView(t,new LinearLayout.LayoutParams(0,dp(58),1));}root.addView(nav);
        if(page.equals("Settings")){settings();return;}if(!detail.isEmpty()){details();return;}
        if(data.items().length()==0){heading("Your cinema, anywhere.");paragraph("Bring your Noir library, history and exact resume times to your phone. Your posters stay here even when the videos are gone.");body.addView(button("Pair with my PC",this::pairInput,true));paragraph("First version · Home Wi-Fi sync · Android 8 or later");return;}
        heading(page.equals("Home")?"Your evening, queued.":page.equals("History")?"Watch history":"Your library");
        if(page.equals("History")){premium.history();return;}if(page.equals("Home"))home();else {premium.filter();EditText q=new EditText(this);q.setSingleLine();q.setTextColor(WHITE);q.setHintTextColor(MUTED);q.setHint("Search movies and shows");q.setText(search);body.addView(q);LinearLayout gridHost=column();body.addView(gridHost);Runnable update=()->{gridHost.removeAllViews();List<List<JSONObject>> groups=groups();groups.removeIf(g->!premium.collection.equals("All")&&(premium.collection.equals("My List")?!g.get(0).optBoolean("listed"):!premium.member(g.get(0),premium.collection)));groups.removeIf(g->!g.get(0).optString("title").toLowerCase(Locale.ROOT).contains(q.getText().toString().toLowerCase(Locale.ROOT))||page.equals("History")&&g.stream().noneMatch(i->DataStore.watched(i)||position(i)>0));if(page.equals("History"))groups.sort((a,b)->Long.compare(recent(b),recent(a)));grid(groups,gridHost);};q.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){search=s.toString();update.run();}public void afterTextChanged(android.text.Editable e){}});update.run();}
    }
    List<List<JSONObject>> groups(){Map<String,List<JSONObject>> m=new LinkedHashMap<>();for(JSONObject i:DataStore.objects(data.items()))m.computeIfAbsent(i.optString("group"),k->new ArrayList<>()).add(i);List<List<JSONObject>> groups=new ArrayList<>(m.values());groups.sort(Comparator.comparing(g->g.get(0).optString("title")));for(List<JSONObject> g:groups)g.sort(Comparator.comparingInt((JSONObject i)->i.optInt("season")==0?999:i.optInt("season")).thenComparingInt(i->i.optInt("episode")));return groups;}
    static double position(JSONObject i){JSONObject p=i.optJSONObject("progress");return p==null?0:p.optDouble("position",0);}
    static boolean completed(JSONObject i){JSONObject p=i.optJSONObject("progress");return p!=null&&p.optBoolean("completed");}
    boolean playable(JSONObject i){return !data.localFile(i.optString("id")).isEmpty()||i.optBoolean("available");}
    static long recent(List<JSONObject> g){return g.stream().mapToLong(DataStore::recent).max().orElse(0);}
    JSONObject continuation(List<JSONObject> g){JSONObject last=g.stream().filter(i->i.optJSONObject("progress")!=null&&(position(i)>0||completed(i))).max(Comparator.comparingLong(DataStore::recent)).orElse(null);if(last==null)return null;if(!completed(last))return playable(last)?last:null;if(last.optBoolean("movie"))return null;int s=last.optInt("season"),e=last.optInt("episode");return g.stream().filter(i->playable(i)&&!completed(i)&&(s==0?i.optInt("season")==0:i.optInt("season")>0)&&(i.optInt("season")>s||i.optInt("season")==s&&i.optInt("episode")>e)).findFirst().orElse(null);}
    void home(){List<List<JSONObject>> groups=groups();List<List<JSONObject>> recent=new ArrayList<>(groups);recent.sort((a,b)->Long.compare(recent(b),recent(a)));List<JSONObject> resume=new ArrayList<>(),next=new ArrayList<>();for(List<JSONObject> g:recent){JSONObject c=continuation(g);if(c!=null&&!g.get(0).optString("status").equals("Dropped")){if(position(c)>0&&!completed(c))resume.add(c);else next.add(c);}}shelf(resume,"Resume watching");shelf(next,"Next episode");premium.extras();
        List<List<JSONObject>> watched=new ArrayList<>();for(List<JSONObject> g:recent)if(g.stream().anyMatch(DataStore::watched))watched.add(g);if(!watched.isEmpty()){heading("Recently watched");grid(watched.subList(0,Math.min(6,watched.size())),body);}List<List<JSONObject>> listed=new ArrayList<>();for(List<JSONObject> g:groups)if(g.get(0).optBoolean("listed"))listed.add(g);if(!listed.isEmpty()){heading("My List");grid(listed,body);}heading("Explore your library");grid(groups,body);}
    void shelf(List<JSONObject> resume,String shelfTitle){if(!resume.isEmpty()){heading(shelfTitle);HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);LinearLayout shelf=new LinearLayout(this);scroll.addView(shelf);body.addView(scroll);for(JSONObject i:resume){LinearLayout card=column();card.setPadding(0,0,dp(14),0);FrameLayout art=new FrameLayout(this);art.addView(poster(i,false),new FrameLayout.LayoutParams(dp(248),dp(142)));TextView play=text("▶",28,GOLD);play.setGravity(Gravity.CENTER);play.setBackground(bg(Color.argb(180,12,12,14),dp(30)));FrameLayout.LayoutParams pp=new FrameLayout.LayoutParams(dp(60),dp(60),Gravity.CENTER);art.addView(play,pp);art.setContentDescription("Resume "+i.optString("title")+" "+episode(i));art.setOnClickListener(v->play(i,false));card.addView(art);TextView title=text(i.optString("title"),16,WHITE);title.setTypeface(null,Typeface.BOLD);title.setPadding(0,dp(10),0,dp(3));title.setOnClickListener(v->open(i));card.addView(title);card.addView(text(episode(i)+" · "+(position(i)>0?"Resume "+DataStore.time(position(i)):"Next episode"),12,MUTED));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(1000);JSONObject p=i.optJSONObject("progress");bar.setProgress((int)(1000*position(i)/Math.max(1,p==null?i.optDouble("duration",1):p.optDouble("duration",1))));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(dp(248),dp(4));bp.setMargins(0,dp(10),0,dp(8));card.addView(bar,bp);shelf.addView(card);}}}
    void grid(List<List<JSONObject>> groups,LinearLayout host){int cols=getResources().getConfiguration().screenWidthDp>=650?4:2;LinearLayout row=null;for(int n=0;n<groups.size();n++){if(n%cols==0){row=new LinearLayout(this);host.addView(row);}List<JSONObject> g=groups.get(n);JSONObject i=g.get(0);LinearLayout card=column();LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.setMargins(0,dp(8),n%cols==cols-1?0:dp(14),dp(18));card.setLayoutParams(cp);int width=(getResources().getConfiguration().screenWidthDp-44-14*(cols-1))/cols;card.addView(poster(i,true),new LinearLayout.LayoutParams(-1,dp(width*1.5f)));TextView title=text(i.optString("title"),15,WHITE);title.setTypeface(null,Typeface.BOLD);title.setPadding(0,dp(9),0,dp(3));card.addView(title);card.addView(text(count(g),11,MUTED));card.addView(text(i.optBoolean("caughtUp")&&!premium.label(g).equals("Dropped")?"Caught up":premium.label(g),11,GOLD));
if(page.equals("History")){ProgressBar progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(g.size());progress.setProgress((int)g.stream().filter(DataStore::watched).count());card.addView(progress,new LinearLayout.LayoutParams(-1,dp(4)));card.addView(button("☆ Rate / note",()->rating(g.stream().max(Comparator.comparingLong(DataStore::recent)).orElse(i)),false));}if(g.stream().anyMatch(DataStore::watched))card.addView(text("✓ Watched"+(i.optBoolean("movie")?"":" episodes"),11,GOLD));if(g.stream().noneMatch(x->x.optBoolean("available")))card.addView(text("Saved history · PC file unavailable",10,MUTED));card.setOnClickListener(v->open(i));row.addView(card);if(n==groups.size()-1)while(row.getChildCount()<cols)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));}if(groups.isEmpty()){TextView t=text("Nothing in this view yet.",14,MUTED);t.setPadding(0,dp(24),0,0);host.addView(t);}}
    ImageView poster(JSONObject i,boolean portrait){ImageView v=new ImageView(this);v.setScaleType(ImageView.ScaleType.CENTER_CROP);v.setBackground(bg(PANEL,dp(12)));v.setContentDescription(i.optString("title")+" artwork");String name=i.optString(portrait?"poster":!i.optString("episodeImage").isEmpty()&&(!data.settings().optBoolean("hideSpoilers",true)||DataStore.watched(i))?"episodeImage":"backdrop");if(name.isEmpty())name=i.optString("poster");File file=data.art(name);if(file.exists()){data.images.execute(()->{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getPath(),o);o.inSampleSize=Math.max(1,o.outWidth/700);o.inJustDecodeBounds=false;Bitmap b=BitmapFactory.decodeFile(file.getPath(),o);runOnUiThread(()->v.setImageBitmap(b));});}return v;}
    String count(List<JSONObject> g){JSONObject i=g.get(0);if(i.optBoolean("movie"))return i.optInt("year")>0?""+i.optInt("year"):"Movie";long regular=g.stream().filter(x->x.optInt("season")>0).count(),special=g.size()-regular,watched=g.stream().filter(DataStore::watched).count();return regular+" episodes"+(special>0?" + "+special+" specials":"")+" · "+watched+" watched";}
    static String episode(JSONObject i){return i.optBoolean("movie")?"Movie":String.format(Locale.ROOT,"S%02d · E%02d",i.optInt("season"),i.optInt("episode"));}
    void open(JSONObject i){detailSeason=-1;detail=i.optString("group");render();}
    void details(){List<JSONObject> group=null;for(List<JSONObject> g:groups())if(g.get(0).optString("group").equals(detail))group=g;if(group==null){detail="";render();return;}JSONObject first=group.get(0);body.addView(button("‹ Back",()->{detail="";render();},false));body.addView(poster(first,false),new LinearLayout.LayoutParams(-1,dp(190)));heading(first.optString("title"));paragraph(count(group)+" · "+first.optString("genres"));JSONObject current=continuation(group);if(current==null)current=group.stream().filter(i->playable(i)&&!completed(i)).findFirst().orElse(first);JSONObject target=current;Button play=button(position(target)>0&&!completed(target)?"▶ Resume "+episode(target)+" · "+DataStore.time(position(target)):"▶ Play "+episode(target),()->play(target,false),true);play.setEnabled(playable(target));body.addView(play);
        boolean listed=first.optBoolean("listed");body.addView(button(listed?"✓ In My List":"+ My List",()->{JSONObject op=data.operation(first.optString("id"),"list");DataStore.put(op,"value",!listed);data.queue(op);data.syncSoon();render();},false));TextView synopsis=text(first.optString("showSummary"),14,MUTED);synopsis.setMaxLines(3);synopsis.setEllipsize(android.text.TextUtils.TruncateAt.END);synopsis.setPadding(0,dp(8),0,dp(8));synopsis.setOnClickListener(v->synopsis.setMaxLines(Integer.MAX_VALUE));synopsis.setTooltipText("Tap to read the full description");body.addView(synopsis);body.addView(button("Reviews & comments",()->reviews(first),false));body.addView(button("Viewing status · "+premium.label(group),()->premium.status(first),false));body.addView(button("Save to collection",()->premium.collections(first),false));if(first.optBoolean("movie")){body.addView(button("Download movie to PC",()->pcDownload(first,false),false));body.addView(button("History, rating & playback options",()->options(first),false));return;}
        final List<JSONObject> allEpisodes=group;TreeSet<Integer> seasons=new TreeSet<>();for(JSONObject i:group)seasons.add(i.optInt("season"));if(detailSeason<0||!seasons.contains(detailSeason))detailSeason=target.optInt("season");String[] seasonLabels=seasons.stream().map(n->n==0?"Specials":"Season "+n).toArray(String[]::new);premium.chips(seasonLabels,detailSeason==0?"Specials":"Season "+detailSeason,v->{detailSeason=v.equals("Specials")?0:Integer.parseInt(v.substring(7));render();});
        JSONObject downloadTarget=group.stream().filter(i->i.optInt("season")==detailSeason).findFirst().orElse(first);body.addView(button("Download Season "+detailSeason+" to PC",()->pcDownload(downloadTarget,true),false));int season=-1;for(JSONObject i:group){if(i.optInt("season")!=detailSeason)continue;if(i.optInt("season")!=season){season=i.optInt("season");heading(season==0?"Specials":"Season "+season);final int selectedSeason=season;long total=group.stream().filter(x->x.optInt("season")==selectedSeason).count(),seen=group.stream().filter(x->x.optInt("season")==selectedSeason&&DataStore.watched(x)).count();paragraph(seen+" / "+total+" watched");ProgressBar progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax((int)total);progress.setProgress((int)seen);body.addView(progress);}LinearLayout row=column();row.setPadding(dp(14),dp(12),dp(14),dp(12));row.setBackground(bg(PANEL,dp(12)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(10));row.setLayoutParams(lp);row.addView(poster(i,false),new LinearLayout.LayoutParams(-1,dp(130)));row.addView(text(episode(i)+"  "+i.optString("episodeTitle"),15,WHITE));if(!data.settings().optBoolean("hideSpoilers",true)||DataStore.watched(i))row.addView(text(i.optString("summary"),12,MUTED));String info=completed(i)?"✓ Watched":position(i)>0?"Resume "+DataStore.time(position(i)):"Not watched";info+=" · "+(!data.localFile(i.optString("id")).isEmpty()?"On phone":i.optBoolean("available")?"Stream from PC":"Video unavailable");row.addView(text(info,12,completed(i)?GOLD:MUTED));row.setOnClickListener(v->options(i));body.addView(row);}}
    void options(JSONObject i){String[] choices={playable(i)?"▶ Watch now / resume":"Video unavailable","Play from beginning",completed(i)?"Mark unwatched":"Mark watched","Link a video on my phone","Reviews & comments","My rating & note","Viewing dates","Add to play queue","Viewing status","Save to collection","Watch & save offline","Correct match / episode numbers","Save offline","Episode description · spoilers","Download to PC","Download this season to PC"};new AlertDialog.Builder(this).setTitle(i.optString("title")+" · "+episode(i)).setItems(choices,(d,n)->{switch(n){case 0:if(playable(i))play(i,false);break;case 1:if(playable(i))play(i,true);break;case 2:data.mark(i.optString("id"),!completed(i));data.syncSoon();render();break;case 3:attachId=i.optString("id");Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"video/*","application/octet-stream"}).addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(pick,9);break;case 4:reviews(i);break;case 5:rating(i);break;case 6:StringBuilder dates=new StringBuilder();for(JSONObject v:DataStore.objects(i.optJSONArray("viewings")))dates.append(java.time.Instant.ofEpochMilli(DataStore.date(v.optString("watchedAt"))).atZone(java.time.ZoneId.systemDefault()).toLocalDate()).append(" · ").append(v.optString("source")).append('\n');new AlertDialog.Builder(this).setTitle("Viewing history").setMessage(dates.length()>0?dates.toString():"No completed viewing recorded yet.").setPositiveButton("OK",null).show();break;case 7:data.queueVideo(i.optString("id"));toast("Added to your phone play queue");break;case 8:premium.status(i);break;case 9:premium.collections(i);break;case 10:download(i,true);break;case 11:premium.match(i);break;case 12:download(i,false);break;case 13:new AlertDialog.Builder(this).setTitle(i.optString("episodeTitle")).setMessage(i.optString("summary")).setPositiveButton("Close",null).show();break;case 14:pcDownload(i,false);break;case 15:pcDownload(i,true);break;}}).show();}
    void rating(JSONObject i){LinearLayout panel=column();panel.setPadding(dp(20),dp(10),dp(20),0);RatingBar stars=new RatingBar(this,null,android.R.attr.ratingBarStyleSmall);stars.setIsIndicator(false);stars.setNumStars(5);stars.setStepSize(1);JSONObject r=i.optJSONObject("review");stars.setRating(r==null?0:r.optInt("rating"));panel.addView(stars);EditText note=new EditText(this);note.setHint("Your private note");note.setText(r==null?"":r.optString("note"));note.setMinLines(3);panel.addView(note);new AlertDialog.Builder(this).setTitle("My rating & note").setView(panel).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{JSONObject op=data.operation(i.optString("id"),"review");DataStore.put(op,"rating",(int)stars.getRating());DataStore.put(op,"note",note.getText().toString());data.queue(op);data.syncSoon();toast("Saved. Syncs when your PC is available.");}).show();}
    boolean launching=false;void play(JSONObject i,boolean restart){if(!playable(i)||launching)return;launching=true;String id=i.optString("id");toast("Checking latest saved position…");data.network.execute(()->{try{data.sync();}catch(Exception ignored){}JSONObject latest=data.item(id);if(latest!=null)try{data.cacheSubtitles(latest);}catch(Exception ignored){}runOnUiThread(()->{launching=false;if(!active)return;if(data.localFile(id).isEmpty()&&!data.online){toast("PC is offline. Connect to the same Wi-Fi, or link a copy on your phone.");return;}startActivity(new Intent(this,PlayerActivity.class).putExtra("id",id).putExtra("restart",restart));});});}void pcDownload(JSONObject item,boolean season){startActivity(new Intent(this,PcDownloadsActivity.class).putExtra("id",item.optString("id")).putExtra("season",season));}
    @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request==9&&result==RESULT_OK&&intent!=null&&intent.getData()!=null){try{getContentResolver().takePersistableUriPermission(intent.getData(),Intent.FLAG_GRANT_READ_URI_PERMISSION);data.localFile(attachId,intent.getData().toString());render();toast("Phone copy linked. You can play it offline.");}catch(Exception e){toast("Couldn't retain access to that file. Try another folder provider.");}}}
    void reviews(JSONObject i){startActivity(new Intent(this,ReviewsActivity.class).putExtra("id",i.optString("id")));}
    void pairInput(){EditText input=new EditText(this);input.setHint("noir://pair?…");input.setSingleLine(false);input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);new AlertDialog.Builder(this).setTitle("Pair with Noir on your PC").setMessage("Open Noir → Settings → Pair a phone. Paste its pairing link here, or scan its QR code with your camera.").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Connect",(d,w)->pair(input.getText().toString())).show();}
    void settings(){heading("Make yourself at home.");paragraph("Noir for Android 0.4.0 · VLC playback");heading("Your PC");paragraph(data.connection+(data.paired()?"\n"+data.address():"")+"\n"+data.pendingCount()+" saved changes waiting to sync");body.addView(button(data.paired()?"Pair again / update PC address":"Pair with my PC",this::pairInput,true));if(data.paired())body.addView(button("Sync now",()->sync(true),false));paragraph("Sync runs when you open Noir, every 15 seconds while it is open, and periodically in the background when Android allows it. PC Noir must be open. Use your home Wi-Fi; internet access alone does not connect to your PC.");body.addView(button("Downloads on my PC",()->startActivity(new Intent(this,PcDownloadsActivity.class)),false));heading("Offline viewing");body.addView(button("Downloads · pause, resume and manage",()->startActivity(new Intent(this,DownloadsActivity.class)),false));paragraph("Choose ‘Watch & save offline’ in an episode’s options, or link a video already on your phone. Noir keeps exact progress locally and sends it when the PC is available again. Deleting the video keeps its poster and viewing history.");heading("About");paragraph("Discover: Cinemeta. TV information: TVmaze (CC BY-SA). Movie information: Wikipedia (CC BY-SA). Artwork belongs to its owners. Playback uses VideoLAN LibVLC under LGPL. This first version syncs with one PC.");}
    void download(JSONObject i,boolean watch){if(!i.optBoolean("available")||!data.online){toast("Connect to your PC to save this video.");return;}try{NoirApp.downloads.enqueue(i);startForegroundService(new Intent(this,DownloadService.class));if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},12);toast("Queued for offline viewing");if(watch)play(i,false);}catch(Exception e){toast(e.getMessage());}}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
